        // Delphi: procedure GetProcedureAddress(var P: Pointer; const ModuleName, ProcName: string)
        public static void GetProcedureAddress(ref IntPtr P, string ModuleName, string ProcName)
        {
            uint ModuleHandle = (uint)0;
            char[] iModuleName = new char[256];
            char[] iProcName = new char[256];
            if (!(P != null))
            {
                Rtl.StrPCopy(iModuleName, ModuleName);
                ModuleHandle = GetModuleHandle(Rtl.StrPas(iModuleName /* @ */));
                if (ModuleHandle == 0)
                {
                    ModuleHandle = LoadLibrary(ModuleName /* @ */);
                    if (ModuleHandle == 0)
                    {
                        throw EJwaLoadLibraryError.CreateResFmt(RsELibraryNotFound /* @ */, new HashSet<string> { ModuleName });
                    }
                }
                Rtl.StrPCopy(iProcName, ProcName);
                P = GetProcAddress(ModuleHandle, ProcName /* @ */) /* Pointer(...) */;
                if (!(P != null))
                {
                    throw EJwaGetProcAddressError.CreateResFmt(RsEFunctionNotFound /* @ */, new HashSet<string> { ModuleName, ProcName });
                }
            }
        }

